package com.arena.core.publicclub;
import static com.arena.core.publicclub.PublicClubContracts.*;
import jakarta.servlet.http.HttpServletRequest;import jakarta.validation.Valid;import lombok.RequiredArgsConstructor;
import org.springframework.web.bind.annotation.*;import org.springframework.security.core.annotation.AuthenticationPrincipal;import org.springframework.security.oauth2.jwt.Jwt;import org.springframework.http.*;import io.swagger.v3.oas.annotations.Operation;
@RestController @RequiredArgsConstructor
public class PublicClubController {
 private final PublicClubService clubs;private final PublicClubHost hosts;private final PublicReservationService bookings;private final ClubCustomerService customers;
 @Operation(summary="Read Owner public site settings",description="Owner only; slug and public booking configuration, no infrastructure mutation.") @GetMapping("/api/academy/public-site")public SiteSettings settings(@AuthenticationPrincipal Jwt jwt){return clubs.settings(jwt);}
 @Operation(summary="Save Owner public site settings",description="Version checked, globally unique validated slug, retained old aliases, explicit slug-change acknowledgement and seven-day change cooldown. Bookings require hours/durations and staff approval.") @PutMapping("/api/academy/public-site")public SiteSettings save(@AuthenticationPrincipal Jwt jwt,@Valid @RequestBody Settings r){return clubs.save(jwt,r);}
 @Operation(summary="Preview own club website",description="Authenticated Owner only. Uses the same public projection for their current academy, including unpublished settings. No academy ID or slug selector is accepted; this does not publish or enable bookings.") @GetMapping("/api/academy/public-site/preview")public ResponseEntity<Site> preview(@AuthenticationPrincipal Jwt jwt){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(clubs.ownerPreview(jwt));}
 @Operation(summary="Preview own club logo",description="Authenticated Owner only; current academy normalized Business Profile image. No tenant selector.") @GetMapping("/api/academy/public-site/preview/logo")public ResponseEntity<byte[]> previewLogo(@AuthenticationPrincipal Jwt jwt){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).contentType(MediaType.IMAGE_PNG).body(clubs.ownerPreviewLogo(jwt));}
 @Operation(summary="Read published club website",description="Anonymous, signed trusted host resolves only active published academies. Strict public Business Profile projection; no private staff, customer or financial data.") @GetMapping("/api/public/club")public ResponseEntity<Site> site(HttpServletRequest r){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(clubs.site(hosts.verifiedSlug(r)));}
 @Operation(summary="Read public club logo",description="Published active club on signed trusted host only. Reuses normalized existing Business Profile image.") @GetMapping("/api/public/club/logo")public ResponseEntity<byte[]> logo(HttpServletRequest r){return ResponseEntity.ok().cacheControl(CacheControl.noStore()).contentType(MediaType.IMAGE_PNG).body(clubs.logo(hosts.verifiedSlug(r)));}
 @Operation(summary="Request public facility reservation",description="Anonymous strict host-scoped request, idempotent and rate limited. Owner configured operating hours/durations and existing availability rules apply. PENDING until authorized staff approval; never starts play or exposes another reservation.") @com.arena.core.documentation.DocumentedErrors({com.arena.core.exception.ErrorCode.TOO_MANY_REQUESTS,com.arena.core.exception.ErrorCode.PUBLIC_BOOKING_INVALID_MOBILE,com.arena.core.exception.ErrorCode.PUBLIC_BOOKING_INVALID_TIME,com.arena.core.exception.ErrorCode.PUBLIC_BOOKING_TIME_INCREMENT,com.arena.core.exception.ErrorCode.PUBLIC_BOOKING_WINDOW,com.arena.core.exception.ErrorCode.PUBLIC_BOOKING_OUTSIDE_HOURS,com.arena.core.exception.ErrorCode.PUBLIC_BOOKING_DURATION,com.arena.core.exception.ErrorCode.PUBLIC_BOOKING_DISABLED,com.arena.core.exception.ErrorCode.PUBLIC_BOOKING_INVALID_DETAILS,com.arena.core.exception.ErrorCode.PUBLIC_BOOKING_FACILITY_UNAVAILABLE,com.arena.core.exception.ErrorCode.PUBLIC_BOOKING_CONFLICT}) @PostMapping("/api/public/club/reservations")public ResponseEntity<BookingReceipt> request(HttpServletRequest r,@Valid @RequestBody Booking body){return ResponseEntity.status(201).cacheControl(CacheControl.noStore()).body(bookings.request(hosts.verifiedSlug(r),body));}
 @Operation(summary="Read public reservation approval inbox",description="Owner/Manager, academy-scoped only. Includes operational unverified customer details.") @GetMapping("/api/academy/public-reservations")public java.util.List<BookingPending> pending(@AuthenticationPrincipal Jwt jwt){return bookings.pending(jwt);}
 public record Decision(boolean approve){}
 @Operation(summary="Approve or reject public reservation",description="Owner/Manager, single atomic decision. Approval reuses existing locked reservation service; conflicts roll back. Session start remains staff controlled.") @PostMapping("/api/academy/public-reservations/{id}/decision")public void decide(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id,@RequestBody Decision r){bookings.decide(jwt,id,r.approve());}
 @Operation(summary="Read club customer directory",description="Owner/Manager only. Name plus mobile identity is unverified; no phone-only merge. Visit count/first/last derive only from actual started sessions.") @GetMapping("/api/academy/customers")public org.springframework.data.domain.Page<ClubCustomerService.View> customers(@AuthenticationPrincipal Jwt jwt,@RequestParam(defaultValue="0")int page){return customers.list(jwt,page);}
 @Operation(summary="Read customer session visits",description="Owner/Manager only, strictly scoped to current academy and customer.") @GetMapping("/api/academy/customers/{id}/visits")public java.util.List<ClubCustomerVisit> visits(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){return customers.history(jwt,id);}
 @Operation(summary="Delete customer personal data",description="Owner only. Clears customer/check-in/reservation contact data and linked session player names; preserves financial amounts and anonymous visit links.") @DeleteMapping("/api/academy/customers/{id}")public void forget(@AuthenticationPrincipal Jwt jwt,@PathVariable Long id){customers.forget(jwt,id);}
}
